changeSet.sql:
UPDATE divipol SET search_vector =
    to_tsvector('spanish',
        unaccent(COALESCE(nomdepto, '') || ' ' ||
        COALESCE(nommipio, '') || ' ' ||
        COALESCE(nompuesto, ''))
    );

CREATE OR REPLACE FUNCTION divipol_search_vector_update()
RETURNS TRIGGER AS $$
BEGIN
    NEW.search_vector := to_tsvector('spanish',
        unaccent(COALESCE(NEW.nomdepto, '') || ' ' ||
        COALESCE(NEW.nommipio, '') || ' ' ||
        COALESCE(NEW.nompuesto, ''))
    );
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS divipol_search_vector_trigger ON divipol;
CREATE TRIGGER divipol_search_vector_trigger
    BEFORE INSERT OR UPDATE ON divipol
    FOR EACH ROW
    EXECUTE FUNCTION divipol_search_vector_update();
